import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2, uint256 amount) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        // Perform some public calls leading to allowance call
        c.approve(addr1, amount);
        c.transferFrom(address(this), addr2, amount);
        // Call allowance to trigger state difference in buggy version
        c.allowance(addr1, addr2);
        // General rule: totalSupply >= sum of all balances
        uint256 totalSupply = c.totalSupply();
        uint256 sumBalances = c.balanceOf(address(this)) + c.balanceOf(addr1) + c.balanceOf(addr2);
        assertTrue(totalSupply >= sumBalances);
    }
}

