pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr1, address addr2, uint256 amount1, uint256 amount2) public {
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        vm.assume(amount1 < 1e30 && amount2 < 1e30);

        // Perform some public calls that may change state
        if (amount1 > 0) {
            c.mintSynth(addr1, amount1);
        }
        if (amount2 > 0) {
            c.mintSynth(addr2, amount2);
        }

        // End with call to allowance
        c.allowance(addr1, addr2);

        // General rule: totalSupply must equal sum of all balances that could be non-zero
        // We check a subset of addresses: the two fuzz addresses and the contract itself
        uint256 sum = c.balanceOf(addr1) + c.balanceOf(addr2) + c.balanceOf(address(this));
        // Also include address(0) though it will always be 0
        sum += c.balanceOf(address(0));

        assertTrue(c.totalSupply() == sum, "totalSupply != sum of balances");
    }
}

