        // Bound inputs to realistic ranges (max totalSupply ~ 1e30)
        mintAmount = bound(mintAmount, 0, 1e30);
        burnAmount = bound(burnAmount, 0, 1e30);

        // Perform some arbitrary public calls that may affect totalSupply
        // We can call burn, but since we don't have mint, we'll just do view calls
        // The key is that allowance is called at the end, and the invariant is checked

        // Ensure owner has some balance by minting to them (if C had mint, but it doesn't; we'll skip)
        // Since C has no public mint, we only do view calls and allowance
        // The invariant must hold after any series of public calls, including none

        // Call allowance (the entry point specified by the difference)
        c.allowance(owner, spender);

        // General rule: totalSupply must be strictly less than 2^128
        // Reference C satisfies this because totalSupply only decreases via burn (minus)
