import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool1, address pool2, address member1, address member2) public {
        vm.assume(pool1 != address(0) && pool2 != address(0) && member1 != address(0) && member2 != address(0));
        vm.assume(pool1 != pool2 && member1 != member2);
        vm.assume(pool1 != address(c) && pool2 != address(c));
        vm.assume(member1 != address(c) && member2 != address(c));
        vm.assume(pool1 != address(this) && pool2 != address(this));
        vm.assume(member1 != address(this) && member2 != address(this));

        // Get initial state
        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialSumLP = c.getmapAddress_LPBalance(pool1) + c.getmapAddress_LPBalance(pool2);
        uint256 initialBalanceC = c.balanceOf(address(c));
        uint256 initialBalanceMember1 = c.balanceOf(member1);
        uint256 initialBalanceMember2 = c.balanceOf(member2);

        // Call allowance to trigger any potential state changes
        c.allowance(member1, member2);

        // Get new state
