import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool, address owner, address spender) public {
        vm.assume(pool != address(0));
        uint256 before = c.getmapAddress_LPBalance(pool);
        c.allowance(owner, spender);
        uint256 after = c.getmapAddress_LPBalance(pool);
        assertTrue(after <= before);
    }
}

