pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool1, address pool2, address owner, address spender) public {
        vm.assume(pool1 != address(0) && pool2 != address(0) && pool1 != pool2);
        vm.assume(owner != address(0) && spender != address(0));

        // Before allowance, get LP balances and debts for both pools
        uint256 lp1before = c.getmapAddress_LPBalance(pool1);
        uint256 lp2before = c.getmapAddress_LPBalance(pool2);
        uint256 debt1before = c.getmapAddress_LPDebt(pool1);
        uint256 debt2before = c.getmapAddress_LPDebt(pool2);

        // Call allowance
        c.allowance(owner, spender);

        // After allowance, get LP balances and debts
        uint256 lp1after = c.getmapAddress_LPBalance(pool1);
        uint256 lp2after = c.getmapAddress_LPBalance(pool2);
        uint256 debt1after = c.getmapAddress_LPDebt(pool1);
        uint256 debt2after = c.getmapAddress_LPDebt(pool2);

        // The total LP balance after should not exceed the total debt after
        // (because if a premium was realized, the LP balance should decrease, not increase)
        assertTrue(lp1after + lp2after <= debt1after + debt2after);
    }
}

