pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address pool, address spender) public {
        vm.assume(pool != address(0) && spender != address(0));
        vm.assume(caller != address(0));

        // Record initial state
        uint initLPBalance = c.getmapAddress_LPBalance(pool);
        uint initLPDebt = c.getmapAddress_LPDebt(pool);
        uint poolLPBalance = IERC20(address(pool)).balanceOf(address(c));

        // Make any call that could affect state, then end with allowance
        vm.prank(caller);
        c.allowance(pool, spender);

        // Get final state
        uint finalLPBalance = c.getmapAddress_LPBalance(pool);
        uint finalLPDebt = c.getmapAddress_LPDebt(pool);
        uint finalPoolLPBalance = IERC20(address(pool)).balanceOf(address(c));

        // Invariant: LP balance of pool never exceeds its debt plus the C contract's own LP tokens of that pool
        assertTrue(finalLPBalance <= finalLPDebt + finalPoolLPBalance);
    }
}

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
}

