pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool, uint256 baseValueLP, uint256 baseValueSynth, uint256 extraLP, uint256 extraSynth) public {
        // Constrain so that premium == 2**18 exactly
        vm.assume(baseValueLP > baseValueSynth);
        uint256 premium = baseValueLP - baseValueSynth;
        vm.assume(premium == 2**18);
        // Ensure overflow is unlikely
        vm.assume(extraLP < type(uint256).max - baseValueLP);
        vm.assume(extraSynth < type(uint256).max - baseValueSynth);
        // We cannot set internal state directly; instead we drive via allowance to observe no change.
        // Since the difference is in realise() triggered indirectly, we fuzz parameters that would condition the path.
        // The assertion: after allowance, mapSynth_LPBalance[pool] remains unchanged from the beginning (if premium == 2^18).
        // We simulate by capturing initial balance via public getter.
        uint256 initialBalance = c.getmapAddress_LPBalance(pool);
        // Trigger allowance call (any parameters)
        vm.assume(pool != address(0));
        c.allowance(pool, address(0xdead));
        uint256 finalBalance = c.getmapAddress_LPBalance(pool);
        // The bug makes the change when premium > 2**18 (strict), so premium == 2**18 should NOT change.
        assertTrue(finalBalance == initialBalance, "mapSynth_LPBalance should not change for premium == 2^18");
    }
}

