pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(address(this), address(this)); 
    }

    function testFuzz_property(address pool, uint256 baseValueLP, uint256 baseValueSynth) public {
        // Bound inputs to realistic values
        baseValueLP = bound(baseValueLP, 0, 1e30);
        baseValueSynth = bound(baseValueSynth, 0, 1e30);

        // Ensure baseValueLP > baseValueSynth and premium is between 2^18+1 and 10^18
        vm.assume(baseValueLP > baseValueSynth);
        uint256 premium = baseValueLP - baseValueSynth;
        vm.assume(premium > 2**18 && premium <= 10**18);

        // Record initial LP balance for the pool
        uint256 initialBalance = c.getmapAddress_LPBalance(pool);

        // Call allowance to trigger any potential side effects
        c.allowance(pool, address(0));

        // Check that LP balance remained unchanged
        // In the reference (threshold 10^18), premium <= 10^18 should NOT modify balance
        // In mutant (threshold 2^18), premium > 2^18 WILL modify balance
        assertTrue(c.getmapAddress_LPBalance(pool) == initialBalance);
    }
}

